s">Unresolved questions (one per line)</label><textarea class="domain-textarea" id="unresolved-questions" maxlength="4000"></textarea></div></div><div class="domain-row-meta" id="policy-comparison" role="status" aria-live="polite">No policy comparison loaded.</div><div class="domain-error" id="policy-error" role="status"></div><div class="domain-controls domain-secondary"><div class="traffic-field"><label for="proposal-format">Export format</label><select class="traffic-select" id="proposal-format"><option value="json">JSON</option><option value="csv">CSV</option><option value="text">Text</option><option value="all">All formats</option></select></div><button class="traffic-button" id="export-proposals" type="button" disabled>Export preview</button><span class="traffic-status" id="proposal-status" role="status" aria-live="polite">No change-request preview loaded.</span></div></div><div class="domain-error" id="proposal-error" role="status"></div><div class="domain-list" id="proposal-rows"><div class="empty">Select a case and trial to load evidence-backed candidates.</div></div><div class="domain-list" id="change-preview"><div class="empty">A change-request preview will show the selected proposal count and redaction summary.</div></div></section>
