u5916\u3092\u524a\u9664','Endpoint environment':'\u30a8\u30f3\u30c9\u30dd\u30a4\u30f3\u30c8\u74b0\u5883','Configured values, resolved routes, and unavailable evidence keep their source labels.':'\u8a2d\u5b9a\u5024\u3001\u89e3\u6c7a\u3057\u305f\u7d4c\u8def\u3001\u5229\u7528\u4e0d\u53ef\u306a\u8a3c\u62e0\u306b\u306f\u30bd\u30fc\u30b9\u8868\u793a\u3092\u4fdd\u6301\u3057\u307e\u3059\u3002','Compare trials':'\u30c8\u30e9\u30a4\u30a2\u30eb\u3092\u6bd4\u8f03','Changed conditions and uncertain matches affect whether a result is causal or observational.':'\u5909\u66f4\u6761\u4ef6\u3068\u4e0d\u78ba\u5b9f\u306a\u4e00\u81f4\u306f\u3001\u7d50\u679c\u3092\u56e0\u679c\u7684\u3068\u898b\u306a\u3059\u304b\u89b3\u6e2c\u7d50\u679c\u3068\u898b\u306a\u3059\u304b\u306b\u5f71\u97ff\u3057\u307e\u3059\u3002','Before trial':'\u6bd4\u8f03\u524d\u306e\u30c8\u30e9\u30a4\u30a2\u30eb','After trial':'\u6bd4\u8f03\u5f8c\u306e\u30c8\u30e9\u30a4\u30a2\u30eb','Compare evidence':'\u8a3c\u62e0\u3092\u6bd4\u8f03','Choose two completed trials to compare their evidence.':'\u8a3c\u62e0\u3092\u6bd4\u8f03\u3059\u308b\u5b8c\u4e86\u6e08\u307f\u30c8\u30e9\u30a4\u30a2\u30eb\u3092\u4e8c\u3064\u9078\u629e\u3057\u307e\u3059\u3002','Evidence bundle':'\u8a3c\u62e0\u30d0\u30f3\u30c9\u30eb','Preview redactions before creating a portable case bundle.':'\u6301\u3061\u51fa\u3057\u53ef\u80fd\u306a\u30b1\u30fc\u30b9\u30d0\u30f3\u30c9\u30eb\u306e\u4f5c\u6210\u524d\u306b\u30de\u30b9\u30af\u7d50\u679c\u3092\u78ba\u8a8d\u3057\u307e\u3059\u3002','Refresh cases':'\u30b1\u30fc\u30b9\u3092\u66f4\u65b0','Case':'\u30b1\u30fc\u30b9','Mask hosts':'\u30db\u30b9\u30c8\u3092\u30de\u30b9\u30af','Mask usernames':'\u30e6\u30fc\u30b6\u30fc\u540d\u3092\u30de\u30b9\u30af','Mask paths':'\u30d1\u30b9\u3092\u30de\u30b9\u30af','Mask identifiers':'\u8b58\u5225\u5b50\u3092\u30de\u30b9\u30af','Destination path (optional)':'\u51fa\u529b\u5148\u30d1\u30b9\uff08\u4efb\u610f\uff09','Preview redactions':'\u30de\u30b9\u30af\u3092\u30d7\u30ec\u30d3\u30e5\u30fc','Export bundle':'\u30d0\u30f3\u30c9\u30eb\u3092\u30a8\u30af\u30b9\u30dd\u30fc\u30c8','Import for offline review':'\u30aa\u30d5\u30e9\u30a4\u30f3\u30ec\u30d3\u30e5\u30fc\u3078\u30a4\u30f3\u30dd\u30fc\u30c8','Imported evidence is read-only and remains attributed to its source.':'\u30a4\u30f3\u30dd\u30fc\u30c8\u3057\u305f\u8a3c\u62e0\u306f\u8aad\u307f\u53d6\u308a\u5c02\u7528\u3067\u3001\u30bd\u30fc\u30b9\u60c5\u5831\u3092\u4fdd\u6301\u3057\u307e\u3059\u3002','Bundle path on this endpoint':'\u3053\u306e\u30a8\u30f3\u30c9\u30dd\u30a4\u30f3\u30c8\u4e0a\u306e\u30d0\u30f3\u30c9\u30eb\u30d1\u30b9','Import bundle':'\u30d0\u30f3\u30c9\u30eb\u3092\u30a4\u30f3\u30dd\u30fc\u30c8','Load more offline evidence':'\u8a3c\u62e0\u3092\u8ffd\u52a0\u8aad\u307f\u8fbc\u307f','Imported bundle retention':'\u30a4\u30f3\u30dd\u30fc\u30c8\u6e08\u307f\u30d0\u30f3\u30c9\u30eb\u4fdd\u6301','Cleanup requires a retention preview and a separate operator confirmation.':'\u524a\u9664\u306b\u306f\u4fdd\u6301\u671f\u9593\u306e\u30d7\u30ec\u30d3\u30e5\u30fc\u3068\u5225\u9014\u306e\u30aa\u30da\u30ec\u30fc\u30bf\u30fc\u78ba\u8a8d\u304c\u5fc5\u8981\u3067\u3059\u3002','Preview cleanup':'\u524a\u9664\u5bfe\u8c61\u3092\u30d7\u30ec\u30d3\u30e5\u30fc','Older than (local time; sent as UTC)':'\u3053\u308c\u3088\u308a\u53e4\u3044\u9805\u76ee\uff08\u30ed\u30fc\u30ab\u30eb\u6642\u523b\u3001UTC\u3067\u9001\u4fe1\uff09','Confirm deletion of eligible imports':'\u5bfe\u8c61\u30a4\u30f3\u30dd\u30fc\u30c8\u306e\u524a\u9664\u3092\u78ba\u8a8d','Clean up imports':'\u30a4\u30f3\u30dd\u30fc\u30c8\u3092\u524a\u9664','No export or import job is running.':'\u30a8\u30af\u30b9\u30dd\u30fc\u30c8\u307e\u305f\u306f\u30a4\u30f3\u30dd\u30fc\u30c8\u306e\u51e6\u7406\u306f\u5b9f\u884c\u3057\u3066\u3044\u307e\u305b\u3093\u3002','Diagnostic workspaces':'\u8a3a\u65ad\u30ef\u30fc\u30af\u30b9\u30da\u30fc\u30b9'
    };
    var trafficFilterIds={host:'filter-host',pathPrefix:'filter-path',method:'filter-method',status:'filter-status',mode:'filter-mode',protocol:'filter-protocol',stage:'filter-stage',source:'filter-source',from:'filter-from',to:'filter-to',preset:'filter-preset'};
    var el=function(id){return document.getElementById(id);};
    var own=function(o,k){return o!==null&&o!==undefined&&Object.prototype.hasOwnProperty.call(o,k);};
    function get(o,names){if(!o)return null;for(var i=0;i<names.length;i++){var n=names[i];if(own(o,n)&&o[n]!==null&&o[n]!==undefined)return o[n];var keys=Object.keys(o);for(var j=0;j<keys.length;j++){if(keys[j].toLowerCase()===n.toLowerCase()&&o[keys[j]]!==null&&o[keys[j]]!==undefined)return o[keys[j]];}}return null;}
    function text(v,fallback){if(v===null||v===undefined||v==='')return fallback||'-';if(typeof v==='object')return fallback||'-';return String(v);}
    var languageAttributes=[];
    function localizedUiText(value){var raw=String(value===null||value===undefined?'':value);if(currentLanguage!=='ja')return raw;if(own(japaneseText,raw))return japaneseText[raw];var translated=raw;Object.keys(japaneseText).sort(function(a,b){return b.length-a.length;}).forEach(function(key){if(translated.indexOf(key)>=0)translated=translated.split(key).join(japaneseText[key]);});return translated;}
    function collectLanguageNodes(){var walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,null,false);var node;while((node=walker.nextNode())){var original=node.nodeValue;var trimmed=original.trim();if(trimmed)languageNodes.push({node:node,original:original,trimmed:trimmed});}var attributes=document.querySelectorAll('[placeholder],[title],[aria-label]');for(var i=0;i<attributes.length;i++){['placeholder','title','aria-label'].forEach(function(name){if(attributes[i].hasAttribute(name))languageAttributes.push({node:attributes[i],name:name,original:attributes[i].getAttribute(name)});});}}
    function applyLanguage(value){currentLanguage=value==='ja'?'ja':'en';document.documentElement.lang=currentLanguage;languageNodes.forEach(function(entry){if(!entry.node.parentNode)return;var leading=entry.original.match(/^\s*/)[0];var trailing=entry.original.match(/\s*$/)[0];entry.node.nodeValue=leading+(currentLanguage==='ja'&&own(japaneseText,entry.trimmed)?japaneseText[entry.trimmed]:entry.trimmed)+trailing;});languageAttributes.forEach(function(entry){if(entry.node.parentNode)entry.node.setAttribute(entry.name,localizedUiText(entry.original));});el('language-switch').value=currentLanguage;try{window.localStorage.setItem(languageStorage,currentLanguage);}catch(error){set('saved-view-status','Language preference applies until this page closes: '+text(error&&error.message,'storage unavailable'));}}
    function set(id,value){el(id).textContent=localizedUiText(value);}
    function request(url,options){return fetch(url,Object.assign({credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}},options||{})).then(function(r){return r.text().then(function(raw){var payload=null;try{payload=raw?JSON.parse(raw):{};}catch(parseError){payload=null;}if(!r.ok){var message=payload?get(payload,['message','errorCode','code']):null;var error=new Error(text(message,'API returned HTTP '+r.status));error.status=r.status;error.errorCode=payload?get(payload,['errorCode','code']):null;throw error;}if(payload===null)throw new Error('Management API returned invalid JSON.');return payload;});});}
    function healthInfo(value){if(value&&typeof value==='object'){var h=get(value,['healthy','isHealthy','listening','ok']);var s=get(value,['status','state','outcome','health']);return {ok:h===true||String(s).toLowerCase()==='healthy'||String(s).toLowerCase()==='running'||String(s).toLowerCase()==='listening',label:text(s,h===true?'Healthy':h===false?'Unhealthy':'Unknown'),detail:text(get(value,['message','reason','errorCode']), '')};}var t=String(value===null?'':value).toLowerCase();return {ok:value===true||t==='healthy'||t==='running'||t==='listening'||t==='true',label:text(value,'Unknown'),detail:''};}
    function endpoint(data,kind){var nested=get(data,[kind]);return text(get(data,[kind+'Endpoint',kind+'Url'])||get(nested,['endpoint','url','address']), 'Not available');}
    function routeText(route){if(route===null||route===undefined)return {main:'Route not reported',meta:'Mihari has not reported an upstream selection'};if(typeof route==='string')return {main:route,meta:''};var kind=text(get(route,['kind','routeKind','type']), 'Route');var endpointText=get(route,['endpoint','proxyEndpoint','address','host']);var source=text(get(route,['source','routeSource']), '');var reason=text(get(route,['reason','errorCode']), '');var main=kind;if(endpointText)main+=' - '+text(endpointText,'');var meta=[source,reason].filter(function(v){return v&&v!=='-';}).join(' - ');return {main:main,meta:meta};}
    function sessionData(data){return get(data,['session'])||data||{};}
    function paintStatus(data){var session=sessionData(data);var sid=text(get(data,['sessionId','id'])||get(session,['sessionId','id']), '-');var state=text(get(data,['effectiveStatus','status','runtimeStatus'])||get(session,['effectiveStatus','status','runtimeStatus']), 'Unknown');var mode=text(get(data,['mode','currentMode'])||get(session,['mode','currentMode']), 'Inspect');var inspect=get(data,['inspectEnabled','mitmEnabled']);if(inspect===null)inspect=get(session,['inspectEnabled','mitmEnabled']);if(inspect===null)inspect=String(mode).toLowerCase()==='inspect';mode=inspect?'Inspect':'Tunnel';
      var proxyH=healthInfo(get(data,['proxyHealth','proxyListenerHealth'])||get(get(data,['proxy']),['health','status','healthy']));var uiH=healthInfo(get(data,['managementHealth','uiHealth'])||get(get(data,['management']),['health','status','healthy']));
      var proxyUrl=endpoint(data,'proxy');var uiUrl=endpoint(data,'management');var ca=get(data,['ca','certificateAuthority'])||{};var caTrusted=get(ca,['trusted','isTrusted','installed']);var caEnabled=get(ca,['enabled','available']);var caState=caTrusted===true?'Trusted':caTrusted===false?'Not trusted':caEnabled===true?'Available':'Not active';
      var route=routeText(get(data,['upstreamRoute','upstream','route']));var active=get(data,['activeConnections','activeConnectionCount','connectionCount']);if(Array.isArray(active))active=active.length;
      var errors=get(data,['errors','runtimeErrors'])||[];var cleanupErrors=get(data,['cleanupErrors','cleanupError']);if(!Array.isArray(errors))errors=errors? [errors]:[];if(!Array.isArray(cleanupErrors))cleanupErrors=cleanupErrors?[cleanupErrors]:[];
      set('session-id',sid);set('footer-session','Session '+sid);set('top-status',state);set('overview-mode',mode);set('mode-state',mode);set('active-count',active===null?'-':String(active));
      var inspectToggle=el('inspect-toggle');if(document.activeElement!==inspectToggle)inspectToggle.checked=inspect;
      el('mode-pill').className='pill '+(inspect?'good':'neutral');set('mode-pill',inspect?'INSPECT':'TUNNEL');
      set('proxy-endpoint',proxyUrl);set('management-endpoint',uiUrl);set('proxy-health',proxyH.label+(proxyH.detail?' - '+proxyH.detail:''));set('management-health',uiH.label+(uiH.detail?' - '+uiH.detail:''));
      set('proxy-health-detail',proxyH.label);set('management-health-detail',uiH.label);set('proxy-health-extra',proxyH.detail||('Loopback endpoint '+(proxyH.ok?'healthy':'health check failed')));set('management-health-extra',uiH.detail||('Loopback endpoint '+(uiH.ok?'healthy':'health check failed')));
      el('proxy-health-dot').className='health-dot '+(proxyH.ok?'':'bad');el('management-health-dot').className='health-dot '+(uiH.ok?'':'bad');
      var caThumb=text(get(ca,['thumbprint','publicThumbprint']), '');var caSubject=text(get(ca,['subject','publicSubject']), '');set('ca-state',caState);set('ca-identity',caSubject|| (caThumb?'Public identity available':'Session trust state'));set('ca-subject',caSubject||'No certificate details');set('ca-thumbprint',caThumb||'-');
      var rt=routeText(get(data,['upstreamRoute','upstream','route']));set('upstream-value',rt.main);set('upstream-meta',rt.meta||'Selected independently from the diagnostic browser proxy');set('upstream-pill',rt.main==='Route not reported'?'Route pending':'Route observed');el('upstream-pill').className='pill '+(rt.main==='Route not reported'?'neutral':'good');
      var runtimeGood=String(state).toLowerCase()==='running'&&proxyH.ok&&uiH.ok;var runtimeBad=!proxyH.ok||!uiH.ok||String(state).toLowerCase()==='failed'||String(state).toLowerCase()==='unhealthy';el('runtime-pill').className='pill '+(runtimeGood?'good':runtimeBad?'bad':'warn');set('runtime-pill',runtimeGood?'Running':runtimeBad?'Listener issue':state);el('top-live').className='live-dot'+(runtimeGood?'':' pulse');
      set('error-count',String(errors.length));set('cleanup-state',cleanupErrors.length?'Cleanup warning':'No cleanup errors');set('error-pill',errors.length||cleanupErrors.length?'Attention':'Clear');el('error-pill').className='pill '+(errors.length||cleanupErrors.length?'warn':'good');
      var errorBar=el('error-bar');if(errors.length||cleanupErrors.length){var first=errors[0]||cleanupErrors[0];var summary=text(typeof first==='object'?get(first,['errorCode','code','message','reason']):first,'Session reported an operational error.');set('error-message',summary);errorBar.className='error-bar visible';}else{errorBar.className='error-bar';}
    }
    function redactedPath(path){var p=text(path,'');var q=p.indexOf('?');if(q>=0)return p.substring(0,q)+'?[REDACTED]';return p;}
    function eventTarget(ev){var d=get(ev,['data'])||{};var host=get(d,['host','destination','authority'])||get(ev,['host']);var path=get(d,['path','urlPath']);var method=get(d,['method']);var target='';if(method)target=text(method,'')+' ';if(host)target+=text(host,'');if(path)target+=(target?' ':'')+redactedPath(path);return target||'-';}
    function formatTime(value){if(!value)return '-';var d=new Date(value);if(isNaN(d.getTime()))return text(value,'-');return d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});}
    function outcomeClass(value){var v=String(value||'').toLowerCase().replace(/[^a-z]/g,'');if(v.indexOf('success')===0||v.indexOf('succeed')===0||v==='ok'||v==='connected')return 'success';if(v.indexOf('fail')>=0||v.indexOf('error')>=0||v.indexOf('reject')>=0)return 'failed';if(v.indexOf('unsupported')>=0||v.indexOf('timeout')>=0)return 'unsupported';return '';}
    function renderEvents(payload){var events=get(payload,['events','observations','items'])||[];if(!Array.isArray(events))events=[];set('event-count-pill',events.length+' events');var tbody=el('event-rows');tbody.textContent='';if(!events.length){var empty=document.createElement('tr');var cell=document.createElement('td');cell.colSpan=5;cell.className='empty';cell.textContent='No observations yet. Launch Edge or configure a client to begin.';empty.appendChild(cell);tbody.appendChild(empty);return;}
      events.slice(0,30).forEach(function(ev){var tr=document.createElement('tr');var d=get(ev,['data'])||{};var values=[formatTime(get(ev,['timestamp','time'])),text(get(ev,['stage']),'-'),eventTarget(ev),text(get(ev,['outcome']),'-'),text(get(ev,['mode']),'-')];values.forEach(function(v,i){var td=document.createElement('td');td.textContent=v;if(i===0)td.className='event-time';if(i===1)td.className='event-stage';if(i===2)td.className='event-target';if(i===3){td.className='event-outcome '+outcomeClass(v);var error=get(d,['errorCode','code']);if(error)td.title=String(error);}tr.appendChild(td);});tbody.appendChild(tr);});}
    function renderFindings(payload){var findings=get(payload,['findings','items'])||[];if(!Array.isArray(findings))findings=[];set('finding-count',String(findings.length));var root=el('finding-rows');root.textContent='';if(!findings.length){var none=document.createElement('div');none.className='empty';none.textContent='No diagnosis is supported by the observations so far.';root.appendChild(none);return;}
      findings.slice(0,12).forEach(function(f){var row=document.createElement('div');row.className='finding';var mark=document.createElement('div');mark.className='finding-mark'+(/reject|invalid|failed|error/i.test(text(get(f,['code','severity']),''))?' red':'');mark.textContent='!';var body=document.createElement('div');var title=document.createElement('div');title.className='finding-title';title.textContent=text(get(f,['summary','title','message']),text(get(f,['code']),'Diagnostic finding'));var code=document.createElement('div');code.className='finding-code';code.textContent=text(get(f,['code']),'finding');var meta=document.createElement('div');meta.className='finding-meta';var scope=text(get(f,['scope']),'');var evidence=get(f,['evidenceIds','evidence']);var count=Array.isArray(evidence)?evidence.length:0;meta.textContent=(scope?'Scope: '+scope:'')+(count?(scope?' - ':'')+count+' evidence item'+(count===1?'':'s'):'');body.appendChild(title);body.appendChild(code);body.appendChild(meta);row.appendChild(mark);row.appendChild(body);root.appendChild(row);});}
