    function selectRequest(key){if(!key)return;trafficSelectedKey=key;trafficDetailPayload=null;setTrafficError('','detail');renderTrafficRows();set('detail-subtitle','Loading request '+key);el('detail-content').textContent='';el('copy-request-key').disabled=false;el('toggle-bookmark').disabled=false;updateBookmarkButton();var serial=++detailRequestSerial;trafficDetailBusy=true;request(API.requestDetail+encodeURIComponent(key)).then(function(payload){if(serial!==detailRequestSerial)return;trafficDetailPayload=payload;renderRequestDetail(payload,false);setTrafficError('','detail');}).catch(function(error){if(serial!==detailRequestSerial)return;set('detail-subtitle','Request detail is stale or unavailable.');var message=document.createElement('div');message.className='traffic-empty';message.textContent='The management API could not load this request detail: '+text(error&&error.message,'detail query failed');el('detail-content').appendChild(message);setTrafficError('Request detail is stale because the management API failed: '+text(error&&error.message,'detail query failed'),'detail');}).finally(function(){if(serial===detailRequestSerial)trafficDetailBusy=false;});}
