    function isBookmarked(key){return !!key&&bookmarks.indexOf(key)>=0;}
    function updateBookmarkButton(){var button=el('toggle-bookmark');var saved=isBookmarked(trafficSelectedKey);button.textContent=saved?'Remove bookmark':'Bookmark';button.title='Browser-local only; this does not change evidence';}
    function loadBookmarks(){try{var raw=window.localStorage.getItem(bookmarkStorage);var values=raw?JSON.parse(raw):[];bookmarks=[];if(Array.isArray(values))values.slice(0,500).forEach(function(value){if(typeof value==='string'&&value.length<=512&&bookmarks.indexOf(value)<0)bookmarks.push(value);});}catch(error){bookmarks=[];set('detail-subtitle','Browser-local bookmarks are unavailable: '+text(error&&error.message,'storage unavailable'));}}
    function toggleBookmark(){if(!trafficSelectedKey)return;var index=bookmarks.indexOf(trafficSelectedKey);if(index>=0)bookmarks.splice(index,1);else if(bookmarks.length<500)bookmarks.push(trafficSelectedKey);else{set('detail-subtitle','The browser-local bookmark limit is 500 request keys.');return;}try{window.localStorage.setItem(bookmarkStorage,JSON.stringify(bookmarks));set('detail-subtitle',isBookmarked(trafficSelectedKey)?'Bookmarked in this browser profile; evidence is unchanged.':'Bookmark removed from this browser profile.');}catch(error){set('detail-subtitle','Bookmark state is only available until this page closes: '+text(error&&error.message,'storage unavailable'));}updateBookmarkButton();renderTrafficRows();}
    function savedFilterValues(){var values={};Object.keys(trafficFilterIds).forEach(function(key){values[key]=String(el(trafficFilterIds[key]).value||'').slice(0,512);});return values;}
    function normalizeSavedViews(value){var normalized=[];if(!Array.isArray(value))return normalized;value.slice(0,20).forEach(function(view){if(!view||typeof view.name!=='string'||!view.name.trim()||!view.filters||typeof view.filters!=='object')return;var filters={};Object.keys(trafficFilterIds).forEach(function(key){if(typeof view.filters[key]==='string')filters[key]=view.filters[key].slice(0,512);});normalized.push({id:String(view.id||normalized.length).slice(0,64),name:view.name.trim().slice(0,48),filters:filters});});return normalized;}
    function saveViews(){try{window.localStorage.setItem(savedViewStorage,JSON.stringify(savedViews));set('saved-view-status','Saved views stay in this browser profile.');}catch(error){set('saved-view-status','This browser could not save local views: '+text(error&&error.message,'storage unavailable'));}}
    function populateSavedViews(selected){var select=el('saved-views');select.textContent='';var prompt=document.createElement('option');prompt.value='';prompt.textContent='Choose a saved view';select.appendChild(prompt);savedViews.forEach(function(view){var option=document.createElement('option');option.value=view.id;option.textContent=view.name;select.appendChild(option);});if(selected)select.value=selected;}
    function loadSavedViews(){try{var raw=window.localStorage.getItem(savedViewStorage);savedViews=normalizeSavedViews(raw?JSON.parse(raw):[]);}catch(error){savedViews=[];set('saved-view-status','Saved views are unavailable in this browser profile.');}populateSavedViews('');}
    function clearTrafficResults(){trafficItems=[];trafficCursor=null;trafficPage=1;trafficRevision=null;renderTrafficRows();el('load-more').disabled=true;}
    function scheduleTrafficQuery(){if(trafficDebounce)window.clearTimeout(trafficDebounce);trafficQuerySerial++;trafficDebounce=window.setTimeout(function(){trafficDebounce=null;trafficCursor=null;clearTrafficResults();refreshTraffic(false);},250);}
    function setDomainError(id,message){var box=el(id);box.textContent=message?localizedUiText(message):'';box.className=message?'domain-error visible':'domain-error';}
    function domainItems(payload,aliases){var items=get(payload,aliases||['items'])||[];return Array.isArray(items)?items:[];}
    function domainResult(payload,aliases){var direct=get(payload,aliases||[]);if(direct!==null)return direct;var result=get(payload,['result']);if(result===null)return null;direct=get(result,aliases||[]);return direct!==null?direct:result;}
    function caseIdOf(value){var id=get(value,['caseId','id','key']);return id===null?'':String(id);}
    function trialIdOf(value){var id=get(value,['trialId','id','key']);return id===null?'':String(id);}
    function populateDomainSelect(id,items,valueOf,labelOf,selected,emptyLabel){var select=el(id);var prior=selected||select.value;select.textContent='';var prompt=document.createElement('option');prompt.value='';prompt.textContent=items.length?'Choose one':emptyLabel;select.appendChild(prompt);items.slice(0,200).forEach(function(item){var option=document.createElement('option');option.value=valueOf(item);option.textContent=labelOf(item);select.appendChild(option);});if(prior)select.value=prior;if(select.value!==prior)select.value='';return select.value;}
    function caseLabel(item){return text(get(item,['title','name']),'Untitled case')+' ('+caseIdOf(item)+')';}
    function trialLabel(item){var label=text(get(item,['operatorBusinessOutcome','businessOutcome']),'');var state=text(get(item,['state','status']),'open');return trialIdOf(item)+' - '+state+(label?' - '+label:'');}
    function setTrialOptions(){var matched=trials.filter(function(item){return !selectedCaseId||String(get(item,['caseId']))===selectedCaseId;});selectedTrialId=populateDomainSelect('trial-picker',matched,trialIdOf,trialLabel,selectedTrialId,'No trials in this case');populateDomainSelect('compare-before',trials,trialIdOf,trialLabel,el('compare-before').value,'No trials available');populateDomainSelect('compare-after',trials,trialIdOf,trialLabel,el('compare-after').value,'No trials available');}
    function selectedCase(){for(var i=0;i<cases.length;i++)if(caseIdOf(cases[i])===selectedCaseId)return cases[i];return null;}
    function renderCaseTrialSummary(){var root=el('case-trial-summary');root.textContent='';var item=selectedCase();if(!item){root.textContent='No case selected.';return;}var caseLine=document.createElement('div');caseLine.textContent='Case: '+text(get(item,['title','name']),'Untitled case')+' ('+caseIdOf(item)+')';root.appendChild(caseLine);var notes=get(item,['notes']);if(Array.isArray(notes))notes.slice(0,20).forEach(function(note){var line=document.createElement('div');line.textContent='Case note: '+text(get(note,['text','note']),typeof note==='string'?note:'');root.appendChild(line);});else if(notes){var noteLine=document.createElement('div');noteLine.textContent='Case notes: '+text(notes,'');root.appendChild(noteLine);}var trial=null;for(var i=0;i<trials.length;i++)if(trialIdOf(trials[i])===selectedTrialId)trial=trials[i];if(!trial){var missing=document.createElement('div');missing.textContent='No trial selected. Start a trial to mark business operations.';root.appendChild(missing);return;}var trialLine=document.createElement('div');trialLine.textContent='Trial: '+trialIdOf(trial)+' | '+text(get(trial,['state','status']),'open')+' | Business outcome: '+text(get(trial,['operatorBusinessOutcome','businessOutcome']),'not recorded');root.appendChild(trialLine);var markers=get(trial,['markers','startMarkers','operationMarkers'])||[];if(!Array.isArray(markers))markers=[markers];markers.slice(0,50).forEach(function(marker){var line=document.createElement('div');line.textContent='Marker: '+text(get(marker,['boundary','kind']),'boundary unknown')+' - '+text(get(marker,['label','name']),'label unknown')+' - '+text(get(marker,['timestamp','timestampUtc']),'time unknown')+(get(marker,['note'])?' - '+String(get(marker,['note'])):'');root.appendChild(line);});}
    function refreshDomainContext(){if(domainBusy)return;domainBusy=true;set('domain-action-status','Loading cases and trials...');Promise.all([request(API.cases),request(API.trials)]).then(function(values){cases=domainItems(values[0],['items','cases']);trials=domainItems(values[1],['items','trials']);var availableCaseIds=cases.map(caseIdOf);if(availableCaseIds.indexOf(selectedCaseId)<0)selectedCaseId=availableCaseIds.length?availableCaseIds[0]:'';populateDomainSelect('case-picker',cases,caseIdOf,caseLabel,selectedCaseId,'No cases yet');if(!selectedCaseId){selectedTrialId='';}setTrialOptions();renderCaseTrialSummary();set('domain-action-status',cases.length+' cases; '+trials.length+' trials loaded');if(activeWorkspace==='dependencies'){loadDependencies();loadProposals();}if(activeWorkspace==='compare')setTrialOptions();}).catch(function(error){setDomainError('dependency-error','Could not load cases and trials: '+text(error&&error.message,'management API failure'));set('domain-action-status','Case and trial data are unavailable.');}).finally(function(){domainBusy=false;});}
    function renderEvidenceReferences(container,refs){if(!Array.isArray(refs))refs=refs?[refs]:[];refs.slice(0,50).forEach(function(ref){var line=document.createElement('div');line.className='domain-evidence';if(typeof ref==='string')line.textContent=ref;else line.textContent='Evidence '+text(get(ref,['sessionId']),'session unknown')+' / '+text(get(ref,['eventId','findingId']),'reference unknown')+' ('+text(get(ref,['source','edgeType','relationship']),'source unknown')+')';container.appendChild(line);});}
    function invalidateProposalPreview(){proposalPreviewId='';proposalPreviewBody=null;el('export-proposals').disabled=true;}
    function renderDependencies(payload){var root=el('dependency-rows');root.textContent='';var items=domainItems(payload,['items','dependencies']);set('dependency-count',items.length+' dependencies');if(!items.length){var empty=document.createElement('div');empty.className='empty';empty.textContent=localizedUiText('No dependency records were returned for this case and trial.');root.appendChild(empty);return;}items.slice(0,200).forEach(function(item){var row=document.createElement('div');row.className='domain-row';var heading=document.createElement('div');heading.className='domain-row-title';heading.textContent=text(get(item,['operationLabel','operation']),'Operation not marked')+' - '+text(get(item,['host','authority']),'Host unknown')+text(get(item,['path','safePath']),'');row.appendChild(heading);var meta=document.createElement('div');meta.className='domain-row-meta';var methods=get(item,['methods']);if(Array.isArray(methods))methods=methods.join(', ');meta.textContent='Methods: '+text(methods,'unknown')+' | Necessity: '+text(get(item,['necessityState']),'observed, necessity unconfirmed')+' | Existing policy: '+text(get(item,['existingPolicyMatch','policyMatch']),'not compared');row.appendChild(meta);var refs=document.createElement('div');renderEvidenceReferences(refs,get(item,['evidenceReferences','evidenceRefs']));row.appendChild(refs);var dependencyId=get(item,['dependencyId','id']);var state=text(get(item,['necessityState']),'');if(dependencyId){dependencyId=String(dependencyId);var selection=document.createElement('label');selection.className='domain-row-meta';var include=document.createElement('input');include.type='checkbox';include.checked=true;include.setAttribute('data-change-dependency-id',dependencyId);include.addEventListener('change',invalidateProposalPreview);selection.appendChild(include);selection.appendChild(document.createTextNode(' '+localizedUiText('Include in change request')));row.appendChild(selection);if(state!=='business_required_confirmed'){var action=document.createElement('button');action.type='button';action.className='traffic-button';action.textContent=localizedUiText('Confirm business required');action.setAttribute('data-dependency-id',dependencyId);action.addEventListener('click',function(){confirmDependency(dependencyId);});row.appendChild(action);}}root.appendChild(row);});}
    function loadDependencies(){if(!selectedCaseId||!selectedTrialId){el('dependency-rows').textContent='';var prompt=document.createElement('div');prompt.className='empty';prompt.textContent='Select a case and trial to load observed destinations.';el('dependency-rows').appendChild(prompt);set('dependency-count','Select a trial');return;}var params=new URLSearchParams();params.set('caseId',selectedCaseId);params.set('trialId',selectedTrialId);request(API.dependencies+'?'+params.toString()).then(function(payload){renderDependencies(payload);setDomainError('dependency-error','');}).catch(function(error){setDomainError('dependency-error','Dependency query failed: '+text(error&&error.message,'management API failure'));});}
    function loadProposals(){invalidateProposalPreview();if(!selectedCaseId||!selectedTrialId){el('proposal-rows').textContent='';var empty=document.createElement('div');empty.className='empty';empty.textContent=localizedUiText('Select a case and trial to load policy candidates.');el('proposal-rows').appendChild(empty);return;}var params=new URLSearchParams();params.set('caseId',selectedCaseId);params.set('trialId',selectedTrialId);params.set('pathMatch',el('proposal-path-match').value);request(API.proposals+'?'+params.toString()).then(function(payload){renderProposalRows(domainItems(payload,['items','proposals']));setDomainError('proposal-error','');}).catch(function(error){setDomainError('proposal-error','Proposal query failed: '+text(error&&error.message,'management API failure'));});}
    function renderProposalRows(items){var root=el('proposal-rows');root.textContent='';if(!items.length){var empty=document.createElement('div');empty.className='empty';empty.textContent=localizedUiText('No policy proposal candidates were returned for this trial.');root.appendChild(empty);return;}items.slice(0,200).forEach(function(item){var row=document.createElement('div');row.className='domain-row';var title=document.createElement('div');title.className='domain-row-title';title.textContent=text(get(item,['proposalType','kind','category']),'Policy candidate')+' - '+text(get(item,['host']),'Host unknown')+text(get(item,['path','safePath']),'');row.appendChild(title);var meta=document.createElement('div');meta.className='domain-row-meta';meta.textContent='Access: '+text(get(item,['access','accessNeed','policyAccess']),'not specified')+' | TLS exclusion: '+text(get(item,['tlsExclusion','exclusionCandidate','localAction']),'not specified')+' | Necessity: '+text(get(item,['necessityState']),'unconfirmed')+' | Existing policy: '+text(get(item,['existingPolicyStatus','existingPolicyMatch','policyMatch']),'not compared');row.appendChild(meta);var reasons=get(item,['requiresConfirmation','limitations']);if(reasons){if(!Array.isArray(reasons))reasons=[reasons];var detail=document.createElement('div');detail.className='domain-row-meta';detail.textContent='Review required: '+reasons.map(function(value){return text(value,'');}).join('; ');row.appendChild(detail);}renderEvidenceReferences(row,get(item,['evidenceReferences','evidenceRefs']));root.appendChild(row);});}
    function confirmDependency(dependencyId){var rationale=el('dependency-rationale').value.trim();if(!rationale){setDomainError('dependency-error','Enter a rationale before confirming business necessity.');el('dependency-rationale').focus();return;}post(API.dependencies+'/'+encodeURIComponent(dependencyId)+'/necessity',{state:'business_required_confirmed',confirmBusinessRequired:true,rationale:rationale}).then(function(result){var state=text(get(result,['state']),'');if(state==='failed')throw new Error(text(get(result,['message','error']),'necessity confirmation failed'));setDomainError('dependency-error','');set('domain-action-status','Business necessity recorded for this dependency.');loadDependencies();loadProposals();}).catch(function(error){setDomainError('dependency-error','Could not record necessity: '+text(error&&error.message,'management API failure'));});}
    function readPolicyDocument(callback){var file=el('policy-file').files&&el('policy-file').files[0];if(!file){selectedPolicyDocument=null;callback(null);return;}if(file.size>6144){setDomainError('policy-error','The neutral policy document must be at most 6 KiB to fit the bounded management request.');return;}var reader=new FileReader();reader.onload=function(){try{var documentValue=JSON.parse(String(reader.result||''));if(!documentValue||typeof documentValue!=='object'||Array.isArray(documentValue)||get(documentValue,['format'])!=='mihari-neutral-url-policy'||Number(get(documentValue,['schemaVersion']))!==1||!Array.isArray(get(documentValue,['rules']))){throw new Error('The selected file is not a version 1 Mihari neutral URL policy JSON document.');}selectedPolicyDocument=documentValue;setDomainError('policy-error','');callback(documentValue);}catch(error){selectedPolicyDocument=null;setDomainError('policy-error','Policy JSON could not be used: '+text(error&&error.message,'invalid policy document'));}};reader.onerror=function(){setDomainError('policy-error','The selected policy document could not be read.');};reader.readAsText(file);}
    function proposalRequestBody(policyDocument){var selected=[];var boxes=document.querySelectorAll('#dependency-rows input[data-change-dependency-id]:checked');for(var i=0;i<boxes.length;i++)selected.push(boxes[i].getAttribute('data-change-dependency-id'));if(!selected.length){throw new Error('Select at least one dependency for the change-request preview.');}var pathMatch=el('proposal-path-match').value;var body={caseId:selectedCaseId,trialId:selectedTrialId,dependencyIds:selected,pathMatch:pathMatch,confirmBroadenedPathPrefix:pathMatch==='pathPrefix'&&el('confirm-broadened-prefix').checked};var action=el('business-action').value.trim();if(action)body.businessAction=action;if(policyDocument)body.policyDocument=policyDocument;var condition=el('reproduction-notes').value.trim();if(condition)body.reproductionConditions={operatorNote:condition};var questions=el('unresolved-questions').value.split(/\r?\n/).map(function(value){return value.trim();}).filter(function(value){return value.length>0;});if(questions.length>20)throw new Error('Enter no more than 20 unresolved questions.');if(questions.length)body.unresolvedQuestions=questions;if(new Blob([JSON.stringify(body)]).size>8192)throw new Error('Reduce the selected dependencies or notes to fit the 8 KiB management request limit.');return body;}
    function renderChangeRequestPreview(payload){var root=el('change-preview');root.textContent='';var row=document.createElement('div');row.className='domain-row';var head=document.createElement('div');head.className='domain-row-title';head.textContent='Change-request preview '+text(get(payload,['previewId']),'unavailable');row.appendChild(head);var facts=document.createElement('div');facts.className='domain-facts';['businessAction','included','omitted','redactionSummary','unresolvedQuestions','sourceCoverage'].forEach(function(name){var value=get(payload,[name]);if(value!==null)appendSafePreview(facts,name,value,0);});row.appendChild(facts);var proposals=get(payload,['proposals'])||[];if(Array.isArray(proposals))renderEvidenceReferences(row,proposals.reduce(function(all,item){var refs=get(item,['evidenceReferences']);if(Array.isArray(refs))all=all.concat(refs);return all;},[]));root.appendChild(row);}
    function previewProposals(){if(!selectedCaseId||!selectedTrialId){setDomainError('proposal-error','Select a case and trial before previewing proposals.');return;}readPolicyDocument(function(policyDocument){var body;try{body=proposalRequestBody(policyDocument);}catch(error){setDomainError('proposal-error',text(error&&error.message,'The change-request fields are invalid.'));return;}post(API.changePreview,body).then(function(payload){var preview=domainResult(payload,['preview']);var previewId=get(preview,['previewId']);proposalPreviewId=previewId===null?'':String(previewId);if(text(get(payload,['state']),'')==='failed'||!proposalPreviewId)throw new Error(text(get(payload,['message','errorCode']),'The change-request preview was not accepted.'));proposalPreviewBody=body;renderChangeRequestPreview(preview);set('proposal-status','Preview ready: '+proposalPreviewId+'; review the selected dependencies and redaction summary before export.');el('export-proposals').disabled=false;setDomainError('proposal-error','');}).catch(function(error){invalidateProposalPreview();setDomainError('proposal-error','Change-request preview failed: '+text(error&&error.message,'management API failure'));});});}
    function comparePolicy(){if(!selectedCaseId||!selectedTrialId){setDomainError('policy-error','Select a case and trial before comparing policy.');return;}readPolicyDocument(function(policyDocument){if(!policyDocument){setDomainError('policy-error','Select a neutral URL policy JSON document first.');return;}post(API.policyCompare,{caseId:selectedCaseId,trialId:selectedTrialId,policyDocument:policyDocument}).then(function(payload){var root=el('policy-comparison');root.textContent='Policy comparison: '+text(get(payload,['coverage']),'unknown coverage')+'; '+comparisonText(get(payload,['items'])||[]);setDomainError('policy-error','');}).catch(function(error){setDomainError('policy-error','Policy comparison failed: '+text(error&&error.message,'management API failure'));});});}
    function exportProposals(){if(!proposalPreviewId||!proposalPreviewBody)return;var body={};Object.keys(proposalPreviewBody).forEach(function(name){body[name]=proposalPreviewBody[name];});body.previewId=proposalPreviewId;body.format=el('proposal-format').value;post(API.changeExport,body).then(function(payload){var result=domainResult(payload,['result']);if(text(get(payload,['state']),'')==='failed'||get(result,['completed'])===false)throw new Error(text(get(payload,['message','errorCode']),'change-request export failed'));var files=get(result,['files'])||[];if(!Array.isArray(files))files=[files];var paths=files.map(function(file){return text(get(file,['relativePath','fileName']),'exported file');}).join(', ');set('proposal-status','Export complete ('+String(files.length)+'): '+(paths||'local output path not reported'));setDomainError('proposal-error','');}).catch(function(error){setDomainError('proposal-error','Change-request export failed: '+text(error&&error.message,'management API failure'));});}
    function performCaseAction(promise,successText,after){set('domain-action-status','Saving operator action...');promise.then(function(payload){if(text(get(payload,['state']),'')==='failed')throw new Error(text(get(payload,['message','error']),'operator action failed'));set('domain-action-status',successText);if(after)after(payload);}).catch(function(error){set('domain-action-status','');setDomainError('dependency-error','Operator action failed: '+text(error&&error.message,'management API failure'));});}
    function createCase(){var title=el('new-case-title').value.trim();if(!title){setDomainError('dependency-error','Enter a case title.');return;}performCaseAction(post(API.cases,{title:title}),'Case created.',function(payload){var item=domainResult(payload,['case']);if(item)selectedCaseId=caseIdOf(item);el('new-case-title').value='';refreshDomainContext();});}
    function createTrial(){if(!selectedCaseId){setDomainError('dependency-error','Select a case before starting a trial.');return;}performCaseAction(post(API.trials,{caseId:selectedCaseId}),'Trial started.',function(payload){var item=domainResult(payload,['trial']);if(item)selectedTrialId=trialIdOf(item);refreshDomainContext();});}
    function addTrialMarker(){if(!selectedTrialId){setDomainError('dependency-error','Select a trial before adding a marker.');return;}var label=el('marker-label').value.trim();if(!label){setDomainError('dependency-error','Enter an operation marker label.');return;}var body={boundary:el('marker-boundary').value,label:label,note:el('marker-note').value};performCaseAction(post(API.trials+'/'+encodeURIComponent(selectedTrialId)+'/markers',body),'Trial marker recorded.',function(){el('marker-label').value='';el('marker-note').value='';refreshDomainContext();});}
