    function initTrafficInspector(){el('tab-overview').addEventListener('click',function(){openWorkspace('overview');});el('tab-traffic').addEventListener('click',function(){openWorkspace('traffic');});Object.keys(trafficFilterIds).forEach(function(key){var input=el(trafficFilterIds[key]);input.addEventListener('input',scheduleTrafficQuery);input.addEventListener('change',scheduleTrafficQuery);});el('traffic-refresh').addEventListener('click',function(){refreshTraffic(false);});el('load-more').addEventListener('click',function(){refreshTraffic(true);});el('traffic-pause').addEventListener('click',function(){trafficPaused=!trafficPaused;trafficQuerySerial++;this.setAttribute('aria-pressed',trafficPaused?'true':'false');this.textContent=trafficPaused?'Resume live':'Pause display';el('traffic-display-state').className='traffic-status'+(trafficPaused?' traffic-stale':'');el('traffic-display-state').textContent=trafficPaused?'Display paused; capture continues':'Live display; capture continues';if(!trafficPaused)refreshTraffic(false);});el('clear-filters').addEventListener('click',function(){Object.keys(trafficFilterIds).forEach(function(key){el(trafficFilterIds[key]).value='';});el('saved-views').value='';scheduleTrafficQuery();});el('save-view').addEventListener('click',function(){var name=el('saved-view-name').value.trim();if(!name){set('saved-view-status','Enter a name for this view.');el('saved-view-name').focus();return;}if(savedViews.length>=20){set('saved-view-status','Remove a saved view before adding another.');return;}var view={id:String(Date.now())+'-'+String(Math.floor(Math.random()*1000000)),name:name.slice(0,48),filters:savedFilterValues()};savedViews.push(view);saveViews();populateSavedViews(view.id);el('saved-view-name').value='';});el('delete-view').addEventListener('click',function(){var id=el('saved-views').value;if(!id){set('saved-view-status','Choose a saved view to delete.');return;}savedViews=savedViews.filter(function(view){return view.id!==id;});saveViews();populateSavedViews('');});el('saved-views').addEventListener('change',function(){var view=null;for(var i=0;i<savedViews.length;i++)if(savedViews[i].id===this.value)view=savedViews[i];if(!view)return;Object.keys(trafficFilterIds).forEach(function(key){el(trafficFilterIds[key]).value=view.filters[key]||'';});scheduleTrafficQuery();});el('copy-request-key').addEventListener('click',function(){if(!trafficSelectedKey)return;var key=trafficSelectedKey;if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(key).then(function(){set('detail-subtitle','Request key copied.');}).catch(function(error){set('detail-subtitle','Could not copy request key: '+text(error&&error.message,'clipboard unavailable'));});}else{set('detail-subtitle','Clipboard access is unavailable; select the request key in the summary.');}});loadSavedViews();}
    function initDomainWorkspaces(){['dependencies','diagnostics','tls','environment','compare','evidence'].forEach(function(name){el('tab-'+name).addEventListener('click',function(){openWorkspace(name);});});el('domain-refresh').addEventListener('click',refreshDomainContext);el('case-picker').addEventListener('change',function(){selectedCaseId=this.value;selectedTrialId='';setTrialOptions();renderCaseTrialSummary();loadDependencies();loadProposals();});el('trial-picker').addEventListener('change',function(){selectedTrialId=this.value;renderCaseTrialSummary();loadDependencies();loadProposals();});el('create-case').addEventListener('click',createCase);el('create-trial').addEventListener('click',createTrial);el('add-marker').addEventListener('click',addTrialMarker);el('complete-trial').addEventListener('click',completeTrial);el('add-case-note').addEventListener('click',addCaseNote);el('dependency-rationale').addEventListener('input',function(){setDomainError('dependency-error','');});el('proposal-refresh').addEventListener('click',loadProposals);el('proposal-path-match').addEventListener('change',function(){invalidateProposalPreview();loadProposals();});['business-action','reproduction-notes','unresolved-questions','policy-file','confirm-broadened-prefix'].forEach(function(id){el(id).addEventListener('input',invalidateProposalPreview);el(id).addEventListener('change',invalidateProposalPreview);});el('compare-policy').addEventListener('click',comparePolicy);el('preview-proposals').addEventListener('click',previewProposals);el('export-proposals').addEventListener('click',exportProposals);el('run-comparison').addEventListener('click',runComparison);el('tls-refresh').addEventListener('click',loadTlsWorkspace);el('add-exclusion').addEventListener('click',addExclusion);el('environment-refresh').addEventListener('click',loadEnvironment);}
    function initLanguage(){collectLanguageNodes();var language='en';try{var saved=window.localStorage.getItem(languageStorage);if(saved==='ja')language='ja';}catch(error){set('saved-view-status','Language preference storage is unavailable: '+text(error&&error.message,'storage unavailable'));}el('language-switch').addEventListener('change',function(){applyLanguage(this.value);});applyLanguage(language);}
    initLanguage();initTrafficInspector();initDomainWorkspaces();initEvidenceWorkspace();loadBookmarks();el('toggle-bookmark').addEventListener('click',toggleBookmark);
    refresh();window.setInterval(refresh,2500);
  })();
  </script>
</body>
</html>
'@
    $tokenJson = ConvertTo-Json -InputObject ([string]$ControlToken) -Compress
    return $html.Replace('__MIHARI_CONTROL_TOKEN__', [string]$tokenJson)
}
